// int main() ist die EINZIGE Stelle, an der ein
// C++-Programm startet – egal wie groß das Projekt ist.

#include <iostream>
#include <string>

int main() {
    std::string name;
    std::cout << "Wie heißt du? ";
    std::getline(std::cin, name);   // ganze Zeile lesen
    std::cout << "Hallo " << name << "!" << std::endl;

    int alter;
    std::cout << "Wie alt bist du? ";
    std::cin >> alter;
    std::cout << "Nächstes Jahr: " << alter + 1 << std::endl;
    return 0;
}
